update public.belkhi_demo_tenders set description='Нужно построить коробку дома 12 × 10 м из газобетона D500: фундамент по проекту, наружные стены, перегородки и двускатная кровля. Участок ровный, геология и проект готовы. Бюджет указан на работы; основные материалы закупает заказчик. В предложении прошу разделить цену по этапам, указать состав бригады и график. Оплата по актам после приёмки этапов.' where position=0 and owner in ('maria','ivan','musa');
